// ============================================================
// PRODUCTION-GRADE UNIVERSAL FILE INGESTION
// ============================================================

// --- Configurable limits (single source of truth) ---
var MAX_FILE_SIZE = 20 * 1024 * 1024; // 20 MB
var SUPPORTED_FORMATS = [
  "jpg","jpeg","png","webp","bmp","tiff","tif","heic","heif",
  "pdf","doc","docx","rtf","txt","csv","xls","xlsx"
];

var item = $input.first();
var body = (item.json && item.json.body) ? item.json.body : (item.json || {});
// --- Auto-detect binary property key ---
// n8n stores multipart files under the form-field name the client used.
// This may be "file", "data", "document", "upload", "image", etc.
// Scan ALL keys and use the first one that carries real binary content.
var binKey = null;
var bin    = null;
if (item.binary && typeof item.binary === "object") {
  var binKeys = Object.keys(item.binary);
  for (var ki = 0; ki < binKeys.length; ki++) {
    var candidate = item.binary[binKeys[ki]];
    if (candidate && (candidate.data || candidate.mimeType || candidate.fileName || candidate.fileSize)) {
      binKey = binKeys[ki];
      bin    = candidate;
      break;
    }
  }
}

// originalFieldName = the multipart form-field name the client chose.
// This is NOT the actual filename — e.g. field "download.pdf" may carry
// a file called "download (1).pdf". They are completely separate.
var originalFieldName = binKey || "";

// --- Context fields ---
var applicationId       = body.applicationId || body.application_id || "APP-UNKNOWN";
var documentId          = body.documentId    || body.document_id    || ("DOC-" + Date.now());
var requestId           = "REQ-" + Date.now() + "-" + Math.floor(Math.random() * 100000);
