var fileId              = "FI-" + requestId;

// --- Binary metadata ---
var reportedFileName  = (bin && bin.fileName) || body.fileName || body.file_name || "";
var reportedMimeType  = ((bin && bin.mimeType) || body.mimeType || body.mime_type || "").toString().toLowerCase().trim();
var fileSize          = Number((bin && (bin.fileSize || bin.fileLength)) || body.fileSize || body.file_size || 0) || 0;
var hasFile           = (bin !== null) || !!(body.mimeType || body.mime_type);

function getExtension(name) {
  if (!name) return "";
  var parts = name.toLowerCase().split(".");
