  if (bin && bin.data && typeof bin.data === "string" && bin.data.length > 0) {
    rawBuf = Buffer.from(bin.data, "base64");
  }
} catch(e) { rawBuf = null; }

// --- Magic-byte signature detection ---
function detectMagicMime(buf) {
