  if (b[0]===0x50 && b[1]===0x4B && b[2]===0x03 && b[3]===0x04) return "application/zip";
  if (buf.length >= 5 && b[0]===0x7B && b[1]===0x5C && b[2]===0x72 && b[3]===0x74 && b[4]===0x66) return "text/rtf";
