    var ftyp = buf.slice(4,8).toString("ascii");
    if (ftyp === "ftyp") {
      var brand = buf.slice(8,12).toString("ascii");
      if (["heic","heis","heim","hevc","hevx"].indexOf(brand) !== -1) return "image/heic";
      if (["mif1","msf1","miaf"].indexOf(brand) !== -1) return "image/heif";
