  if (IMAGE_MIMES.indexOf(mime) !== -1 || IMAGE_EXTS.indexOf(ext) !== -1) return "IMAGE";
  if (SPREADSHEET_MIMES.indexOf(mime) !== -1 || SPREADSHEET_EXTS.indexOf(ext) !== -1) return "SPREADSHEET";
