var fileSubKind = null;
if (fileCategory === "TEXT" || detectedExtension === "txt") fileSubKind = "txt";
else if (detectedExtension === "rtf" || detectedMimeType.indexOf("rtf") !== -1) fileSubKind = "rtf";
else if (detectedExtension === "docx" || detectedMimeType.indexOf("wordprocessingml") !== -1) fileSubKind = "docx";
else if (detectedExtension === "doc" || detectedMimeType.indexOf("msword") !== -1) fileSubKind = "doc";

// isEmpty: use rawBuf length when decoded; fall back to descriptor fileSize
// (in binaryMode:separate the raw bytes are stored externally and rawBuf
//  may be null inside the Code node even when a real file was uploaded).
var isEmpty;
if (rawBuf !== null) {
  isEmpty = rawBuf.length === 0;
} else if (bin && fileSize > 0) {
  isEmpty = false;
} else {
  isEmpty = !hasFile || fileSize === 0;
}
