      } else {
        var ascii = [];
        var run = "";
        var limit = Math.min(buf.length, 65536);
        for (var i = 0; i < limit; i++) {
          var c = buf[i];
          if (c >= 32 && c <= 126) {
            run += String.fromCharCode(c);
          } else {
            if (run.length >= 5) ascii.push(run.trim());
            run = "";
          }
        }
        if (run.length >= 5) ascii.push(run.trim());
        extractedText = ascii
          .filter(function(s) { return /[a-zA-Z]{3,}/.test(s); })
          .join(" ");
        extractionNote = "doc_ascii_scan";
